def filter_palindromes(words: list[str]) -> list[str]:
    """Filter palindromes in place."""
    i = 0
    while i < len(words):
        if words[i].lower() != words[i].lower()[::-1]:
            words.pop(i)
        else:
            i += 1
    return words
```
Removes non‑palindromes directly from the original list and returns it.
